mapper.select:
SELECT so.id, so.order_no, so.platform_order_no, so.warehouse_id, w.name AS warehouse_name, so.receiver_name, so.receiver_phone, so.receiver_address, so.order_status, so.total_amount, so.remark, so.paid_at, so.shipped_at, so.finished_at, so.deleted, so.created_at, so.updated_at FROM sales_order so LEFT JOIN warehouse w ON so.warehouse_id = w.id WHERE so.deleted = 0
AND so.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND so.platform_order_no LIKE CONCAT('%', #{platformOrderNo}, '%')
AND so.receiver_name LIKE CONCAT('%', #{receiverName}, '%')
AND so.receiver_phone = #{receiverPhone}
AND so.order_status = #{orderStatus}
AND so.warehouse_id = #{warehouseId}
ORDER BY id DESC

mapper.update:
UPDATE sales_order
SET order_status = #{orderStatus}
WHERE id = #{id} AND deleted = 0
